/**
 * What reaching the limit means for `allowed` (Payrudder never refuses usage events). HARD (also unspecified): allowed turns false at the
 * limit. SOFT: allowed stays true and the usage over the limit is billed at the meter's price, which the package must have. NOTIFY: allowed
 * stays true; only the alerts are sent.
 *
 */
export type QuotaMode = "QUOTA_MODE_UNSPECIFIED" | "QUOTA_MODE_HARD" | "QUOTA_MODE_SOFT" | "QUOTA_MODE_NOTIFY";

/** What a limit counts over, in the tenant's time zone. Unspecified is the month (the billing period). A year is the calendar year (twelve billing periods); a lifetime limit never starts again. */
export type QuotaWindow = "QUOTA_WINDOW_UNSPECIFIED" | "QUOTA_WINDOW_MONTH" | "QUOTA_WINDOW_HOUR" | "QUOTA_WINDOW_DAY" | "QUOTA_WINDOW_WEEK" | "QUOTA_WINDOW_YEAR" | "QUOTA_WINDOW_LIFETIME";

